<script lang="ts">import {api} from '$lib/api';const tabs=['GENERAL','BUSINESS','EDUCATION','HEALTHCARE'];let tab='GENERAL',name='',phone='',email='',message='',sending=false,success='',error='';async function submit(){sending=true;error='';try{await api('/enquiries',{method:'POST',body:JSON.stringify({type:tab,name,phone,email,message})});success='Thank you. Your enquiry has been received.';name=phone=email=message=''}catch(e){error=e instanceof Error?e.message:'Could not submit'}finally{sending=false}}</script><svelte:head><title>Apply / Enquiry — Bengal Port</title></svelte:head><section class="page-hero"><div class="wrap"><span class="eyebrow">APPLY / ENQUIRY</span><h1>Tell us where you want to go.</h1><p>Choose the enquiry type and share the essentials. Our team will guide the next step.</p></div></section><section class="section"><div class="wrap box"><div class="tabs" role="tablist">{#each tabs as t}<button class:active={tab===t} onclick={()=>tab=t}>{t}</button>{/each}</div>{#if success}<p class="success">{success}</p>{/if}{#if error}<p class="error">{error}</p>{/if}<form onsubmit={(e)=>{e.preventDefault();submit()}}><div class="form-grid"><div class="field"><label for="name">Full Name *</label><input id="name" bind:value={name} required minlength="2"/></div><div class="field"><label for="phone">Phone Number *</label><input id="phone" bind:value={phone} required/></div><div class="field"><label for="email">Email</label><input id="email" type="email" bind:value={email}/></div><div class="field"><label for="interest">{tab==='BUSINESS'?'Company / business interest':tab==='EDUCATION'?'Desired country / program':tab==='HEALTHCARE'?'Treatment / destination preference':'Subject'}</label><input id="interest"/></div></div><div class="field full"><label for="message">Enquiry Information *</label><textarea id="message" bind:value={message} required rows="6"></textarea></div><button class="btn" disabled={sending}>{sending?'SENDING…':'SUBMIT ENQUIRY'}</button>{#if tab==='BUSINESS'}<a class="business-link" href="/business/apply">Need a factory or supplier visit? Complete the detailed business visit application →</a>{/if}</form></div></section><style>.box{max-width:900px;background:#fff;padding:38px;border-radius:20px;box-shadow:var(--shadow)}.tabs{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid #e0e3e7;margin-bottom:30px}.tabs button{border:0;background:none;padding:16px 8px;font-weight:800;color:#687282;border-bottom:3px solid transparent}.tabs button.active{color:var(--navy);border-color:var(--gold)}.full{margin:18px 0}.business-link{display:block;color:var(--gold);font-weight:700;margin-top:20px}@media(max-width:600px){.tabs{grid-template-columns:1fr 1fr}.box{padding:22px}}</style>
